import{_ as o,H as t,f as a,i as s}from"./chunks/framework.DWsZwgB4.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),r={name:"guide/troubleshooting.md"};function d(n,e,i,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page lists errors you may see, why they happen and how to fix them. Each heading is the message or symptom as you see it.</p><h2 id="optionserror-the-database-options-could-not-be-located-loaded" tabindex="-1"><code>OptionsError: The database options could not be located/loaded.</code> <a class="header-anchor" href="#optionserror-the-database-options-could-not-be-located-loaded" aria-label="Permalink to &quot;`OptionsError: The database options could not be located/loaded.`&quot;">​</a></h2><p>The message goes on to list the accepted export shapes.</p><p><strong>Cause:</strong> no data source file was found, or no file has an export in one of the <a href="./data-source.html#accepted-export-shapes">accepted shapes</a> (a <code>DataSource</code>, a promise of one, a default export function without parameters returning one, or <code>DataSourceOptions</code>), and the environment names no driver (<code>DB_TYPE</code> or a <code>DB_URL</code> with a scheme).</p><p><strong>Fix:</strong></p><ul><li>Export a <code>DataSource</code>, e.g. <code>export const dataSource = new DataSource(options)</code>, a default export factory function returning one, or the options object itself. Named functions, functions with a required parameter and classes are not called.</li><li>Point the CLI at the file with <code>-d</code>, e.g. <code>-d src/config/orm.ts</code>. The path is relative to <code>--root</code>.</li><li>Outside <code>tsx</code> and <code>ts-node</code>, <code>src</code> in the path is rewritten to your tsconfig <code>outDir</code> (default <code>dist</code>). The path as given is used only when the rewritten one does not exist, and a <code>.ts</code> file only when TypeScript support is detected (<code>tsx</code>, <code>ts-node</code>, or Node&#39;s type stripping: behind <code>--experimental-strip-types</code> on older Node 22 releases, on by default since Node 22.18, and off with <code>--no-experimental-strip-types</code>). Type stripping does not support decorators, so with <code>@Entity()</code> classes in <code>src</code> run the CLI with <code>tsx</code> or against a build. If a stale build in <code>outDir</code> shadows your sources, pass <code>--preserveFilePaths</code> or run the CLI with <code>tsx</code>.</li></ul><p>See <a href="./data-source.html#discovery">Discovery</a>.</p><h2 id="syntaxerror-the-requested-module-typeorm-does-not-provide-an-export-named-datasourceoptions" tabindex="-1"><code>SyntaxError: The requested module &#39;typeorm&#39; does not provide an export named &#39;DataSourceOptions&#39;</code> <a class="header-anchor" href="#syntaxerror-the-requested-module-typeorm-does-not-provide-an-export-named-datasourceoptions" aria-label="Permalink to &quot;`SyntaxError: The requested module &#39;typeorm&#39; does not provide an export named &#39;DataSourceOptions&#39;`&quot;">​</a></h2><p><strong>Cause:</strong> Node loads your <code>.ts</code> file itself (type stripping, behind <code>--experimental-strip-types</code> on older Node 22 releases and on by default since Node 22.18). It removes type annotations but keeps every import, so an import of a type fails at runtime.</p><p><strong>Fix:</strong> import types with <code>import type</code>:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { DataSource } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;typeorm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { DataSourceOptions } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;typeorm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>See <a href="./data-source.html#discovery">Discovery</a>.</p><h2 id="syntaxerror-invalid-or-unexpected-token-at-a-decorator" tabindex="-1"><code>SyntaxError: Invalid or unexpected token</code> at a decorator <a class="header-anchor" href="#syntaxerror-invalid-or-unexpected-token-at-a-decorator" aria-label="Permalink to &quot;`SyntaxError: Invalid or unexpected token` at a decorator&quot;">​</a></h2><p><strong>Cause:</strong> Node&#39;s type stripping does not support decorators such as <code>@Entity()</code>, so plain Node cannot load your entity files.</p><p><strong>Fix:</strong> run the CLI with <code>tsx</code> (<code>tsx ./node_modules/typeorm-extension/bin/cli.mjs ...</code>), or run it against your build.</p><p>See <a href="./cli.html">CLI</a>.</p><h2 id="error-cannot-find-module-src" tabindex="-1"><code>Error: Cannot find module &#39;src/...&#39;</code> <a class="header-anchor" href="#error-cannot-find-module-src" aria-label="Permalink to &quot;`Error: Cannot find module &#39;src/...&#39;`&quot;">​</a></h2><p><strong>Cause:</strong> your code imports through a tsconfig path alias or <code>baseUrl</code> (e.g. <code>from &#39;src/common/base.entity&#39;</code>). Node does not read tsconfig, so it cannot resolve the import when the seeder or the data source file is loaded.</p><p><strong>Fix:</strong> use relative imports, or a runtime that resolves tsconfig paths (<code>tsx</code> does). For a build, use relative imports or a build step that rewrites the aliases.</p><p>See <a href="./recipes/production-build.html">Running from a build</a>.</p><h2 id="seeders-factories-or-entities-are-not-found-when-you-run-the-build" tabindex="-1">Seeders, factories or entities are not found when you run the build <a class="header-anchor" href="#seeders-factories-or-entities-are-not-found-when-you-run-the-build" aria-label="Permalink to &quot;Seeders, factories or entities are not found when you run the build&quot;">​</a></h2><p><strong>Cause:</strong> outside <code>tsx</code> and <code>ts-node</code>, the library assumes compiled code. It replaces <code>src</code> in string paths (<code>entities</code>, <code>migrations</code>, <code>subscribers</code>, <code>seeds</code>, <code>factories</code>, <code>-d</code>) with the tsconfig <code>outDir</code> and <code>.ts</code> with <code>.js</code>. If your build does not mirror <code>src</code> below <code>outDir</code> (e.g. a monorepo that builds to <code>dist/apps/&lt;name&gt;</code>), the globs match nothing. A glob falls back to the original <code>src</code> pattern only when every file it matches can be loaded by the runtime.</p><p><strong>Fix:</strong> point the globs at the build output, pass <code>--preserveFilePaths</code> with paths that are already correct, or pass classes instead of globs.</p><p>See <a href="./recipes/production-build.html">Running from a build</a>.</p><h2 id="entitymetadatanotfounderror-no-metadata-for-user-was-found" tabindex="-1"><code>EntityMetadataNotFoundError: No metadata for &quot;User&quot; was found.</code> <a class="header-anchor" href="#entitymetadatanotfounderror-no-metadata-for-user-was-found" aria-label="Permalink to &quot;`EntityMetadataNotFoundError: No metadata for &quot;User&quot; was found.`&quot;">​</a></h2><p><strong>Cause:</strong> the entity is not part of the data source. Its class is missing from <code>entities</code>, or the <code>entities</code> glob matches no file (see the build rewrite above).</p><p><strong>Fix:</strong> add the entity class to <code>entities</code>, or fix the glob. A data source that uses the entity must list it, also when only a seeder or factory uses it.</p><p>See <a href="./data-source.html">Data Source</a>.</p><h2 id="error-no-seeder-factory-is-registered-for-the-entity-user" tabindex="-1"><code>Error: No seeder factory is registered for the entity: User</code> <a class="header-anchor" href="#error-no-seeder-factory-is-registered-for-the-entity-user" aria-label="Permalink to &quot;`Error: No seeder factory is registered for the entity: User`&quot;">​</a></h2><p><strong>Cause:</strong> <code>factoryManager.get(User)</code> found no factory for the entity name. The <code>factories</code> glob matched no file, so no <code>setSeederFactory()</code> call ran. Without configuration, the glob is <code>src/database/factories/**/*{.ts,.js}</code>.</p><p><strong>Fix:</strong> set <code>factories</code> in the data source options (or <code>DB_FACTORIES</code>) to the files that call <code>setSeederFactory()</code>, or pass the factories themselves: <code>factories: [userFactory]</code>.</p><p>See <a href="./seeding.html#factories">Factories</a>.</p><h2 id="error-database-app-does-not-exist-when-you-create-a-postgres-database" tabindex="-1"><code>error: database &quot;app&quot; does not exist</code> when you create a postgres database <a class="header-anchor" href="#error-database-app-does-not-exist-when-you-create-a-postgres-database" aria-label="Permalink to &quot;`error: database &quot;app&quot; does not exist` when you create a postgres database&quot;">​</a></h2><p><strong>Cause:</strong> postgres needs a database to connect to before it can run <code>CREATE DATABASE</code>. Without an initial database, the postgres client connects to the database named like the user (or <code>PGDATABASE</code>).</p><p><strong>Fix:</strong> name an existing database, usually <code>postgres</code>:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">typeorm-extension</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --initialDatabase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span></code></pre></div><p>In code, pass <code>initialDatabase: &#39;postgres&#39;</code> to <code>createDatabase()</code> or <code>dropDatabase()</code>.</p><p>See <a href="./database.html#create">Database</a>.</p><h2 id="variables-from-env-are-ignored" tabindex="-1">Variables from <code>.env</code> are ignored <a class="header-anchor" href="#variables-from-env-are-ignored" aria-label="Permalink to &quot;Variables from `.env` are ignored&quot;">​</a></h2><p><strong>Cause:</strong> the library reads <code>process.env</code> only. It does not load <code>.env</code> files.</p><p><strong>Fix:</strong> load the file when the process starts, e.g. <code>node --env-file=.env ...</code> or <code>tsx --env-file=.env ...</code>, or load it at the top of your data source file (e.g. with <code>dotenv</code>). The environment is read once and cached: in tests, call <code>resetEnv()</code> after you change <code>process.env</code>.</p><p>See <a href="./data-source.html#environment-variables">Environment variables</a>.</p><h2 id="error-duplicate-seeds-name" tabindex="-1"><code>Error: Duplicate seeds: &lt;name&gt;</code> <a class="header-anchor" href="#error-duplicate-seeds-name" aria-label="Permalink to &quot;`Error: Duplicate seeds: &lt;name&gt;`&quot;">​</a></h2><p><strong>Cause:</strong> two seeders have the same class name. The class name is the seeder&#39;s name, so anonymous classes (<code>export default class implements Seeder</code>) can end up with the same name, e.g. <code>default</code>.</p><p><strong>Fix:</strong> give each seeder class its own name.</p><p>See <a href="./seeding.html#tracking">Tracking</a>.</p><h2 id="can-i-revert-seeds" tabindex="-1">Can I revert seeds? <a class="header-anchor" href="#can-i-revert-seeds" aria-label="Permalink to &quot;Can I revert seeds?&quot;">​</a></h2><p>No. A seeder has only <code>run()</code>, no <code>down()</code> step, so the library cannot undo what it wrote. Seeders run on every <code>seed run</code> unless tracking is on (<code>seedTracking: true</code> or <code>track = true</code> on the class). A tracked seeder is recorded by class name in the <code>seeds</code> table and skipped from then on. To run it again, delete its row. To remove the data, write a migration, or in development drop and create the database (<code>db drop</code>, then <code>db create</code>).</p><p>See <a href="./seeding.html#tracking">Tracking</a>.</p>',50)])])}const g=o(r,[["render",d]]);export{u as __pageData,g as default};
